// Comparison spec for the SAM family (Dragon 32/64/200, Tano, CoCo 1/2/2B and clones).
// diag.asm (generated by gen-diag.js) is our own 16K firmware, installed in place of the BASIC ROM(s);
// the second bank differs only in its id byte at $BF00 so ROM switching can be observed.
const path = require('path'), fs = require('fs'), cp = require('child_process');
const { loadEmu, assembleFile, romImage, writeRoms, writeProfileRoms, mameConfigArgs, writeCfg } = require('../lib/firmware');
const { workDir } = require('../lib/workdir');
const { REGS } = require('../lib/regs');

const RESET_FRAMES = 5;   // reset.asm: frames between reaching SYNC and the Reset press
// split 16K firmware images into the profile's ROM slots
function slotData(profile, bank0, bank1) {
  const out = {};
  for (const sl of profile.roms) {
    if (sl.chip) continue;                        // the 200-E's character generator (genChargen below)
    const img = sl.bank === 1 ? bank1 : bank0;
    out[sl.id] = img.slice(sl.at - 0x8000, sl.at - 0x8000 + sl.size);
  }
  return out;
}
function images(file, generator) {
  const asm = assembleFile(path.join(__dirname, file), '6809', generator);
  const bank0 = romImage(asm, 0x8000, 0x4000, 0x12);
  const bank1 = bank0.slice(); bank1[0x3F00] = 0x22;
  return { asm, bank0, bank1 };
}
// A 4K character generator built from our own pattern, never a real ROM: every byte's low seven bits spell
// out the (code, raster line) it was fetched for, so a comparison proves which address the VDG asked the
// chip for. Bit 7 alternates: the 200-E's display data has AS low (bit 7 clear) for text.
function genChargen() {
  const rom = new Uint8Array(0x1000);
  for (let a = 0; a < rom.length; a++) rom[a] = (a & 0x7F) ^ ((a >> 7) & 1 ? 0x80 : 0);
  return rom;
}
// MAME's LK1 "Inverse Video" link is a configuration switch, not a command-line option: it is written into a
// .cfg file in the work directory (MAME reads <cfg_directory>/<system>.cfg at start). "Normal" (the default)
// leaves INV low; "Inverse" ties it high, inverting every glyph the character generator returns.
function inverseCfg(work, system, on) {
  const dir = path.join(work, 'cfg');
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, `${system}.cfg`),
    `<?xml version="1.0"?>\n<mameconfig version="10">\n\t<system name="${system}">\n\t\t<input>\n` +
    `\t\t\t<port tag="LK1" type="CONFIG" mask="1" defvalue="1" value="${on ? 0 : 1}" />\n` +
    `\t\t</input>\n\t</system>\n</mameconfig>\n`);
}
// the two Hi-Res firmware variants (gen-hires.js builds one per run, so both are generated first)
function hiresImages(kind) {
  const gen = path.join(__dirname, 'gen-hires.js');
  for (const k of ['tandy', 'max3']) cp.execFileSync('node', [gen, k], { stdio: 'ignore' });
  return images(kind === 'max3' ? 'hires-max3.asm' : 'hires.asm');
}
function machine(profileId, slots, config = {}) {
  const m = loadEmu().createMachine(profileId, Object.assign({ mameCompat: true }, config));
  m.setRoms(slots);
  m.reset(true);
  return m;
}
// a profile's ROM slot images ({ slotId: bytes }): the firmware for the bus sockets and our generator for
// the character-generator chip, so both emulators run the same firmware
function withChip(profile, slots) {
  const out = Object.assign({}, slots);
  if (profile.roms.some((s) => s.chip)) out.chargen = genChargen();
  return out;
}
function mameArgs(profile, resolved) {
  return ['-ext', '', ...mameConfigArgs(resolved)];
}

module.exports = {
  genChargen,
  withChip,
  inverseCfg,
  family: 'sam',
  // lockstep trace comparison (regenerate: rebuild diag.asm from gen-diag.js first). A machine with less
  // than 64K runs the firmware variant laid out to fit its RAM (gen-diag.js --ram-k=N).
  trace(profileId, { regenerate = true, config = {}, work = workDir(profileId) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const ramK = resolved.ram || 64;
    const file = ramK >= 32 ? 'diag.asm' : `diag-${ramK}k.asm`;
    const gen = regenerate && path.join(__dirname, 'gen-diag.js');
    if (gen && ramK < 32) cp.execFileSync('node', [gen, `--ram-k=${ramK}`], { stdio: 'ignore' });
    const { asm, bank0, bank1 } = images(file, gen && ramK >= 32 ? gen : undefined);
    const slots = withChip(profile, slotData(profile, bank0, bank1));
    return {
      label: profileId, system: profile.mame, work, seconds: 4, args: mameArgs(profile, resolved),
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      // the file names the MAME in use asks for (lib/firmware.js romFilesFor): 0.289 split the Dragon 32's
      // 16K image in two and renamed the Tano's
      install: () => { writeProfileRoms(work, profile, slots); if (profile.charGen) inverseCfg(work, profile.mame, resolved.inverseVideo); },
      machine: () => machine(profileId, slots, config),
      instructions: 300000,
    };
  },
  // the SAM CPU rate firmware (rate.asm): timed loops at every rate, mid-field switches, map type 1
  rate(profileId, { config = {}, work = workDir(`${profileId}-rate`), file = 'rate.asm', stopAtHalt = false } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const { asm, bank0, bank1 } = images(file);
    const slots = withChip(profile, slotData(profile, bank0, bank1));
    const files = {};
    for (const sl of profile.roms) for (const f of sl.files) files[f] = slots[sl.id];
    return {
      label: `${profileId} ${file}`, system: profile.mame, work, seconds: 4, args: mameArgs(profile, resolved),
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'), files, asm, slots, stopAtHalt,
      install: () => { writeProfileRoms(work, profile, slots); if (profile.charGen) inverseCfg(work, profile.mame, resolved.inverseVideo); },
      machine: (cfg = config) => machine(profileId, slots, cfg),
      instructions: 400000,
    };
  },
  // PIA1 port B's input pins (pia1b.asm; CoCo wiring: MAME coco.cpp pia1_pb_r)
  pia1b(profileId, opts = {}) { return this.rate(profileId, Object.assign({ file: 'pia1b.asm', work: `/tmp/mame-diff/${profileId}-pia1b` }, opts)); },
  // The Reset button (reset.asm): MAME's Lua presses it (machine:soft_reset) RESET_FRAMES frames after the firmware
  // has reached each SYNC (PHASE goes 1, then 2). The lockstep resets ours when MAME's trace shows the reset
  // (resetOurs); pressAfter is the same rule in frames for the MAME-free regression gate.
  reset(profileId, opts = {}) {
    const t = this.rate(profileId, Object.assign({ file: 'reset.asm', work: workDir(`${profileId}-reset`), stopAtHalt: true }, opts));
    const sym = (n) => t.asm.symbols.get(n);
    const phase = sym('PHASE');
    return Object.assign(t, {
      label: `${profileId} reset.asm`, seconds: 6, resetPc: sym('RESET'), phaseAddr: phase,
      // (MAME runs the script again after each soft reset; the global keeps this to the first run)
      luaPrelude: `local sp = manager.machine.devices[":maincpu"].spaces["program"]
if not _G.cloadm_reset then
  _G.cloadm_reset = true
  for a = 0x71, 0x73 do sp:write_u8(a, 0) end
  for a = ${phase}, ${phase + 0x1F} do sp:write_u8(a, 0) end
  local seen, wait = 0, -1
  emu.register_frame_done(function()
    local p = sp:read_u8(${phase})
    if p > seen then seen = p; wait = ${RESET_FRAMES} end
    if wait > 0 then wait = wait - 1 elseif wait == 0 then wait = -1; manager.machine:soft_reset() end
  end)
end
`,
      // our side of a press. MAME's cycle count starts again at 0 after a soft reset, so the lockstep compares the
      // cycles from the first instruction after it afresh (beforeOurs returns true): when the button is pressed is
      // outside the machine, and this firmware does nothing after a reset that depends on when that was.
      resetOurs(m) { m.reset(false); },
      // the regression gate's presses: RESET_FRAMES frames after PHASE rises, at a frame's end
      pressAfter: RESET_FRAMES,
    });
  },
  // the SAM memory-size (M1/M0) and page (P1) bits: what a low address aliases to (memsize.asm)
  memsize(profileId, opts = {}) { return this.rate(profileId, Object.assign({ file: 'memsize.asm', work: workDir(`${profileId}-memsize`) }, opts)); },
  // The floating bus: what $FF60-$FFBF returns with no cartridge fitted (floating.asm; MAME coco.cpp
  // floating_bus_read). tests/bus.test.js pins MAME's rule without MAME; this is the same rule against MAME
  // itself, on every SAM machine, instruction for instruction (the values in A and in RAM are compared).
  // The firmware is 39 instructions; stop the comparison at its HALT loop rather than through it.
  floating(profileId, opts = {}) {
    return this.rate(profileId, Object.assign({ file: 'floating.asm', work: `/tmp/mame-diff/${profileId}-floating`, stopAtHalt: true }, opts));
  },
  // Hi-Res joystick interface (hires.asm or hires-max3.asm): how long the interface takes to fire for a stick
  // position. The comparison runs MAME with the interface selected through its cfg (its Lua API cannot change
  // a port CONFIG field at run time; lib/firmware.js writeCfg) and its joystick ports set from Lua. MAME's two
  // circuits are 535 + 5850 x position microseconds (Tandy) and 380 + 2885 x position (CoCo Max 3).
  // cfg: 1 = Tandy Hi-Res in the right port, 2 = CoCo Max 3 style in the right port (MAME's HIRES_INTF_TAG).
  hires(profileId, { kind = 'tandy', sticks = [0, 341, 682, 1023], work = workDir(`${profileId}-hires-${kind}`) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const option = kind === 'max3' ? 'max3-right' : 'tandy-right';
    const resolved = Emu.resolveConfig(profileId, { mameCompat: true, hires: option });
    const { asm, bank0 } = hiresImages(kind);
    const slots = slotData(profile, bank0, bank0.slice());
    const files = {};
    for (const sl of profile.roms) for (const f of sl.files) files[f] = slots[sl.id];
    return {
      label: `${profileId} hires ${kind}`, system: profile.mame, work, files, asm, sticks, kind,
      // the sample layout: PHASE at $0100, then ten 16-bit counts from $0110
      phaseAddr: 0x100, sampleAddr: 0x110, samples: 10,
      loopUs: 44.66,       // one pass of the firmware's polling loop, measured from its own counts
      cfgIntf: kind === 'max3' ? 2 : 1,
      install: () => { writeProfileRoms(work, profile, slots); writeCfg(work, profile.mame, kind === 'max3' ? 2 : 1); },
      machine: () => machine(profileId, slots, { hires: option }),
      resolved,
    };
  },
  // the same firmware in instruction lockstep with MAME: every register and every cycle must match, to HALT.
  // MAME's stick position comes from its Lua (a live input); ours is the same position on the 6-bit axis.
  hiresLockstep(profileId, { kind = 'tandy', pos = 682, work = workDir(`${profileId}-hires-lockstep-${kind}`) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const option = kind === 'max3' ? 'max3-right' : 'tandy-right';
    const resolved = Emu.resolveConfig(profileId, { mameCompat: true, hires: option });
    const { asm, bank0 } = hiresImages(kind);
    const slots = slotData(profile, bank0, bank0.slice());
    const files = {};
    for (const sl of profile.roms) for (const f of sl.files) files[f] = slots[sl.id];
    const axis = Math.round(pos * 63 / 1023);
    return {
      label: `${profileId} hires ${kind} lockstep, stick ${pos}`, system: profile.mame, work, files, asm, axis,
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      args: ['-ext', 'max', ...mameConfigArgs(resolved)],
      // MAME: the interface from the cfg, the stick position from Lua
      luaPrelude: `local iop = manager.machine.ioport
iop.ports[":joystick_rx"].fields["Right Joystick X"]:set_value(${pos})
iop.ports[":joystick_ry"].fields["Right Joystick Y"]:set_value(${pos})`,
      luaPostlude: `local space = manager.machine.devices[":maincpu"].spaces["program"]
local n = 0
emu.register_frame_done(function()
  n = n + 1
  if space:read_u8(0x100) == 10 or n > 300 then manager.machine:exit() end
end)`,
      install: () => { writeProfileRoms(work, profile, slots); writeCfg(work, profile.mame, kind === 'max3' ? 2 : 1); },
      machine: () => { const m = machine(profileId, slots, { hires: option }); m.joy[0] = [axis, axis]; return m; },
      instructions: 400000,
    };
  },
  // mid-line video changes swept across the beam (raster.asm, from gen-raster.js; lib/raster.js)
  raster(profileId, { regenerate = true, config = {}, work = workDir(`${profileId}-raster`) } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const gen = require('./gen-raster');
    const ramK = resolved.ram || 64;
    // Below 32K the phase/field counters and the stack do not fit at their usual addresses: generate the
    // variant laid out into the fitted RAM. Its display data still needs 8K, so 4K cannot run the sweep.
    // A machine with a character generator wired as the 200-E's runs its own variant (gen-raster.js --chargen).
    const chargen = !!profile.charGen;
    if (chargen && ramK < 64) throw new Error(`${profileId}: the character-generator raster firmware is laid out for 64K`);
    if (regenerate) {
      if (ramK < 32) cp.execFileSync('node', [path.join(__dirname, 'gen-raster.js'), `--ram-k=${ramK}`], { stdio: 'ignore' });
      else if (chargen) cp.execFileSync('node', [path.join(__dirname, 'gen-raster.js'), '--chargen'], { stdio: 'ignore' });
      else gen.write();
    }
    const file = chargen ? 'raster-chargen.asm' : ramK >= 32 ? 'raster.asm' : `raster-${ramK}k.asm`;
    const { asm, bank0 } = images(file);
    const slots = withChip(profile, slotData(profile, bank0, bank0));
    return {
      label: profileId, system: profile.mame, work, seconds: 6, args: mameArgs(profile, resolved),
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      install: () => { writeProfileRoms(work, profile, slots); if (profile.charGen) inverseCfg(work, profile.mame, resolved.inverseVideo); },
      machine: () => machine(profileId, slots, config),
      phaseAddr: ramK >= 32 ? 0x7000 : 0x0800, fieldAddr: ramK >= 32 ? 0x7001 : 0x0801,
      file, cases: chargen ? gen.chargenCases : gen.cases, fields: gen.FIELDS,
      // the plain frame: the one read while the counter reads FIELDS - LEAD_IN, which on these machines is the
      // last lead-in field (frames lag the counter by one), not the first: that can still show the character
      // bank the previous case left on the 200-E (MAME samples it once per field, before the case's setup)
      plain: gen.FIELDS - gen.LEAD_IN,
    };
  },
  // the SAM display-counter probe (samv.asm, run-samv.js): an address-tagged picture at SAM V 0, then V 1
  samv(profileId, { config = {} } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const { bank0 } = images('samv.asm');
    const slots = withChip(profile, slotData(profile, bank0, bank0));
    const files = {};
    for (const sl of profile.roms) for (const f of sl.files) files[f] = slots[sl.id];
    return { files, args: mameArgs(profile, resolved), inverse: profile.charGen ? resolved.inverseVideo : null,
      machine: () => machine(profileId, slots, config), frames: 80 };
  },
  // printer firmware (lib/printer.js): the Dragons' parallel port, or the bit-banger's serial printer on the others
  printer(profileId, { config = {}, work = `/tmp/mame-diff/${profileId}-printer` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const parallel = profile.lineage === 'dragon';
    const { asm, bank0 } = images(parallel ? 'printer-parallel.asm' : 'printer-serial.asm');
    const slots = withChip(profile, slotData(profile, bank0, bank0));
    const files = {};
    for (const sl of profile.roms) for (const f of sl.files) files[f] = slots[sl.id];
    return {
      label: profileId, system: profile.mame, work, seconds: 12, args: ['-ext', '', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      install: () => writeProfileRoms(work, profile, slots),
      machine: () => machine(profileId, slots, config),
      instructions: parallel ? 50000 : 3000000, doneAddr: 0x7001,
      // reset makes PIA1's port A all inputs, pulled high: the strobe is high and the printer takes PIA0 port B,
      // also all inputs, $FF (MAME 6821pia.cpp device_reset; dragon.cpp pia1_pa_changed)
      atReset: parallel ? [0xFF] : [],
      text: parallel ? 'CLOADM PRINTER TEST, DRAGON PARALLEL PORT\r\n' : 'CLOADM PRINTER TEST, COCO SERIAL PORT, 600 BAUD\r\n',
    };
  },
  // bit-banger serial port in loopback (serial-loopback.asm; MAME -rs232 loopback): lockstep, then every byte read back
  serial(profileId, { config = {}, work = `/tmp/mame-diff/${profileId}-serial` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    if (profile.acia) return this.acia(profileId, { config, work });
    if (profile.lineage === 'dragon') throw new Error(`${profileId}: no serial port (the Dragon 32 has a parallel printer port only)`);
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const { asm, bank0 } = images('serial-loopback.asm');
    const slots = slotData(profile, bank0, bank0);
    const files = {};
    for (const sl of profile.roms) for (const f of sl.files) files[f] = slots[sl.id];
    const data = asm.symbols.get('DATA'), end = asm.symbols.get('DATAEND');
    return {
      label: `${profileId} serial loopback`, system: profile.mame, work, seconds: 4, args: ['-ext', '', '-rs232', 'loopback', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      install: () => writeProfileRoms(work, profile, slots),
      // the loopback is plugged in before the machine is reset, as MAME starts with it
      machine: () => {
        const m = loadEmu().createMachine(profileId, Object.assign({ mameCompat: true }, config));
        m.setRoms(slots); m.bitBanger.attach('loopback'); m.reset(true);
        return m;
      },
      instructions: 200000,
      // after HALT: the bytes sent (from the ROM) and the bytes read back ($7102 on), none different
      result: (m) => {
        const sent = [...bank0.slice(data - 0x8000, end - 0x8000)], back = [...m.ram.slice(0x7102, 0x7102 + sent.length)];
        return { ok: m.ram[0x7000] === 0xFF && m.ram[0x7001] === 0 && sent.every((v, i) => v === back[i]), sent, back };
      },
    };
  },
  // the Dragon 64's 6551 ACIA in loopback (acia.asm; MAME -rs232 loopback): lockstep, then the bytes read back
  acia(profileId, { config = {}, work = `/tmp/mame-diff/${profileId}-acia` } = {}) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const resolved = Emu.resolveConfig(profileId, Object.assign({ mameCompat: true }, config));
    const { asm, bank0, bank1 } = images('acia.asm');
    const slots = withChip(profile, slotData(profile, bank0, bank1));
    const files = {};
    for (const sl of profile.roms) for (const f of sl.files) files[f] = slots[sl.id];
    // the bytes the configuration loop sends, and what comes back (7-bit formats drop bit 7)
    const cfgs = asm.symbols.get('CFGS') - 0x8000, sent = [];
    for (let i = cfgs; bank0[i]; ) {
      const ctrl = bank0[i], n = bank0[i + 2];
      for (let k = 0; k < n; k++) sent.push(((ctrl >> 5) & 3) === 1 ? bank0[i + 3 + k] & 0x7F : bank0[i + 3 + k]);
      i += 3 + n;
    }
    return {
      // MAME's patch box as a loopback plug that holds the handshake lines asserted: RxD from TxD, CTS, DSR and
      // DCD asserted (rs232/patchbox.cpp: TXD = 0, ASSERT = 13). MAME's plain loopback leaves them high here, and
      // with CTS high the 6551 never transmits (dragon64 does not wire the ACIA's RTS and DTR to the port).
      label: `${profileId} ACIA loopback`, system: profile.mame, work, seconds: 4,
      // (set in MAME's configuration file, which it applies before the machine is reset: the 6551 takes its DSR
      // and DCD status bits at reset)
      args: ['-ext', '', '-rs232', 'patch', ...mameConfigArgs(resolved)],
      regs: REGS, waitOps: ['CWAI', 'SYNC'], haltPc: asm.symbols.get('HALT'),
      install: () => {
        writeProfileRoms(work, profile, slots);
        const conf = (n, dflt, v) => `      <port tag=":rs232:patch:CONF${n}" type="CONFIG" mask="15" defvalue="${dflt}" value="${v}" />`;
        require('fs').mkdirSync(path.join(work, 'cfg'), { recursive: true });
        require('fs').writeFileSync(path.join(work, 'cfg', `${profile.mame}.cfg`), `<?xml version="1.0"?>
<mameconfig version="10">
  <system name="${profile.mame}">
    <input>
${[conf(1, 1, 0), conf(3, 3, 13), conf(4, 4, 13), conf(6, 6, 13)].join('\n')}
    </input>
  </system>
</mameconfig>
`);
      },
      // the loopback is plugged in before the machine is reset, as MAME starts with it
      machine: () => {
        const m = loadEmu().createMachine(profileId, Object.assign({ mameCompat: true }, config));
        m.setRoms(slots); m.acia.attachSerial('loopback', { handshake: 'asserted' }); m.reset(true);
        return m;
      },
      instructions: 400000,
      result: (m) => {
        const back = [...m.ram.slice(0x7400, 0x7400 + sent.length)];
        return { ok: m.ram[0x7000] === 0xFF && sent.every((v, i) => v === back[i]), sent, back };
      },
    };
  },
  // video firmware for the regression test: every display mode, phase counter at $7000
  video(profileId) {
    const Emu = loadEmu(), profile = Emu.profiles[profileId];
    const { bank0 } = images('vdg.asm');
    return { machine: () => machine(profileId, withChip(profile, slotData(profile, bank0, bank0))), frames: 680 };
  },
};
